create table users (id bigint generated by default as identity primary key, username varchar(80) not null unique, password varchar(255) not null, role varchar(16) not null check(role in ('USER','ADMIN')), version bigint not null default 0);
create table bookings (id bigint generated by default as identity primary key, user_id bigint not null references users(id), room_id bigint, hotel_id bigint, auto_select boolean not null, start_date date not null, end_date date not null, status varchar(16) not null check(status in ('PENDING','CONFIRMED','CANCELLED')), created_at timestamp with time zone not null, request_id uuid not null, request_hash varchar(64) not null, trace_id varchar(64) not null, error_status integer, error_code varchar(80), version bigint not null default 0, unique(user_id,request_id), check(end_date > start_date), check(status <> 'CONFIRMED' or room_id is not null));
create index ix_bookings_history on bookings(user_id,created_at,id);
create index ix_bookings_recovery on bookings(status,created_at);
create table booking_attempts (id uuid primary key, booking_id bigint not null references bookings(id), room_id bigint not null, start_date date not null, end_date date not null, unique(booking_id,room_id));
create table compensation_tasks (id uuid primary key references booking_attempts(id), booking_id bigint not null references bookings(id), state varchar(16) not null check(state in ('READY','DONE')), attempts integer not null default 0, next_attempt_at timestamp with time zone not null, last_error varchar(300), version bigint not null default 0);
create index ix_compensation_due on compensation_tasks(state,next_attempt_at);
